import{_ as a,o,c as r,a2 as e}from"./chunks/framework.BHRys-F3.js";const g=JSON.parse('{"title":"【筑基·04】你已经筑基了吗？——码农修炼体系四座地基","description":"","frontmatter":{},"headers":[],"relativePath":"zhuji/04-are-you-zhuji.md","filePath":"zhuji/04-are-you-zhuji.md","lastUpdated":1786977271000}'),n={name:"zhuji/04-are-you-zhuji.md"};function p(l,t,s,i,d,u){return o(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="【筑基·04】你已经筑基了吗-——码农修炼体系四座地基" tabindex="-1">【筑基·04】你已经筑基了吗？——码农修炼体系四座地基 <a class="header-anchor" href="#【筑基·04】你已经筑基了吗-——码农修炼体系四座地基" aria-label="Permalink to &quot;【筑基·04】你已经筑基了吗？——码农修炼体系四座地基&quot;">​</a></h1><blockquote><p><strong>码农修仙传 · 筑基期 · 第4篇</strong> 我是玄芯散人，带你从炼气修到大乘。</p></blockquote><hr><h2 id="境界标识" tabindex="-1">境界标识 <a class="header-anchor" href="#境界标识" aria-label="Permalink to &quot;境界标识&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>╔══════════════════════════════════╗</span></span>
<span class="line"><span>║     筑基期 · 第4篇               ║</span></span>
<span class="line"><span>║     你已经筑基了吗？              ║</span></span>
<span class="line"><span>║     预计阅读：8分钟               ║</span></span>
<span class="line"><span>╚══════════════════════════════════╝</span></span></code></pre></div><hr><h2 id="修仙引入" tabindex="-1">修仙引入 <a class="header-anchor" href="#修仙引入" aria-label="Permalink to &quot;修仙引入&quot;">​</a></h2><p>你是不是写了两年代码，但一被问到这些问题就卡壳：</p><p>&quot;进程和线程到底什么区别？&quot; &quot;TCP三次握手为什么是三次不是两次？&quot; &quot;哈希表底层是怎么实现的？&quot;</p><p>你会写代码，会调API，能搞定业务需求。但这些&quot;基础&quot;问题一问就懵。</p><p><strong>你不是写不动代码，你是筑基不稳。</strong></p><p>在码农修仙体系里，炼气期是&quot;会写代码&quot;，筑基期是&quot;懂原理&quot;。两者之间有一道坎——很多人工作五年十年，实际修为还卡在炼气后期，从没真正筑基。</p><p>今天讲清楚：筑基到底要筑什么，以及怎么判断自己有没有筑基成功。</p><hr><h2 id="硬核主体-筑基四座地基" tabindex="-1">硬核主体：筑基四座地基 <a class="header-anchor" href="#硬核主体-筑基四座地基" aria-label="Permalink to &quot;硬核主体：筑基四座地基&quot;">​</a></h2><p>筑基期要打四座地基。缺任何一座，后续修为都是空中楼阁。</p><h3 id="第一座地基-数据结构与算法" tabindex="-1">第一座地基：数据结构与算法 <a class="header-anchor" href="#第一座地基-数据结构与算法" aria-label="Permalink to &quot;第一座地基：数据结构与算法&quot;">​</a></h3><p>这是筑基最核心的地基。<strong>数据结构是法器，算法是功法。</strong></p><p>为什么这么比喻？</p><p>法器是修仙者用来对敌的工具——剑、印、镜、鼎。数据结构对程序而言就是工具——数组、链表、树、图、哈希表。你用什么数据结构，决定了你的程序能怎么操作数据，就像修仙者用什么法器，决定了能打什么仗。</p><p>功法是修仙者修炼的内核——决定了灵气怎么运转。算法对程序而言就是内核——决定了计算怎么进行。排序、查找、动态规划、贪心，这些是程序运转的内在逻辑。</p><p><strong>判断你是否筑基成功的标准：</strong></p><p>问你一个问题——给你一个无序数组，要找出第K大的元素，你怎么做？</p><ul><li>炼气期回答：排序，然后取第K个。时间复杂度O(n log n)。</li><li>筑基期回答：用小顶堆，维护K个元素，O(n log k)。</li></ul><p>如果你想到的是前者，你还在炼气期。如果你能解释为什么堆更优，并且知道堆的底层是怎么实现的（完全二叉树+数组存储），你的数据结构与算法地基筑成了。</p><p><strong>筑基丹（学习资源）：</strong></p><ul><li>《算法导论》——经典但厚重，选读</li><li>MIT 6.006（B站有中文字幕版）——视频课程，更直观</li><li>LeetCode刷题——实战验证，按专题刷</li></ul><hr><h3 id="第二座地基-操作系统" tabindex="-1">第二座地基：操作系统 <a class="header-anchor" href="#第二座地基-操作系统" aria-label="Permalink to &quot;第二座地基：操作系统&quot;">​</a></h3><p><strong>操作系统是天道规则。</strong> 它决定了所有程序运行的基本法则——谁能用CPU、谁能用内存、谁能读写文件。不管你写什么代码，都在操作系统定的规则里活动。</p><p>筑基期不需要你懂内核源码，但要懂这几个核心概念：</p><p><strong>进程与线程。</strong> 进程是独立运行的程序实例，线程是进程内的执行单元。一个进程可以有多个线程，共享进程的资源。</p><p>为什么这重要？因为你写的每一行代码都跑在某个线程里，理解线程调度才能理解为什么并发会有问题——为什么需要锁，为什么会有死锁，为什么volatile不够用。</p><p><strong>内存管理。</strong> 虚拟内存、分页、内存映射。你new一个对象，底层发生了什么？为什么Stack Overflow和OutOfMemoryError是两种不同的错误？理解这些，你才能写出内存高效的代码，才能调优性能问题。</p><p><strong>文件系统与IO。</strong> 文件本质是什么？读写文件时操作系统做了什么？为什么IO慢，怎么优化？这些知识在写高性能应用时至关重要。</p><p><strong>判断你是否筑基成功的标准：</strong></p><p>问：你写的程序从&quot;点击运行&quot;到&quot;输出结果&quot;，中间发生了什么？</p><ul><li>炼气期回答：程序跑起来了，出了结果。</li><li>筑基期回答：操作系统创建进程，分配虚拟内存空间，加载可执行文件到内存，CPU从入口点开始执行指令，遇到系统调用时切换到内核态，结果通过IO输出到终端或文件。</li></ul><p>如果你能把这个链路大致讲清楚，操作系统地基筑成了。</p><p><strong>筑基丹：</strong></p><ul><li>《操作系统导论》（OSTEP）——免费在线，讲得最通透</li><li>《深入理解计算机系统》（CSAPP）——不只是操作系统，是整个计算机系统的底层认知</li></ul><hr><h3 id="第三座地基-数据库" tabindex="-1">第三座地基：数据库 <a class="header-anchor" href="#第三座地基-数据库" aria-label="Permalink to &quot;第三座地基：数据库&quot;">​</a></h3><p><strong>不是&quot;会用SQL&quot;，是&quot;懂原理&quot;。</strong></p><p>会写SELECT、JOIN、GROUP BY，这是炼气期。筑基期要懂：</p><p><strong>索引。</strong> B+树是什么，为什么数据库索引用B+树而不是二叉搜索树？聚簇索引和非聚簇索引的区别是什么？什么时候索引会失效？</p><p>这些问题不是空谈——你线上SQL慢了，不懂索引原理，你连explain出来的执行计划都看不懂，怎么优化？</p><p><strong>事务。</strong> ACID是什么？隔离级别有哪几种？为什么默认隔离级别是RC或RR？MVCC怎么实现的？</p><p>这些在写并发逻辑、处理数据一致性时是核心知识。</p><p><strong>判断你是否筑基成功的标准：</strong></p><p>问：一张1000万行的表，SELECT * FROM users WHERE age = 25，怎么判断这个查询会不会走索引？</p><ul><li>炼气期回答：应该会吧。</li><li>筑基期回答：看WHERE条件字段有没有索引，看字段选择性高不高，用EXPLAIN看执行计划，看type是不是ref/range，看扫描行数估算。</li></ul><p>如果你能答出这个链路，数据库地基筑成了。</p><p><strong>筑基丹：</strong></p><ul><li>《MySQL技术内幕：InnoDB存储引擎》——讲InnoDB实现原理</li><li>《数据库系统概念》——经典教材，讲通用数据库原理</li></ul><hr><h3 id="第四座地基-计算机网络" tabindex="-1">第四座地基：计算机网络 <a class="header-anchor" href="#第四座地基-计算机网络" aria-label="Permalink to &quot;第四座地基：计算机网络&quot;">​</a></h3><p><strong>网络是修仙界的传送阵。</strong> 现代应用几乎没有不联网的，不懂网络，你写的每一个接口都像黑盒——不知道数据怎么出去，怎么回来。</p><p>筑基期要懂：</p><p><strong>TCP/IP。</strong> 为什么TCP要三次握手？为什么断开要四次挥手？TIME_WAIT是什么，为什么要有？这些不是八股文，是线上故障排查的基础——端口耗尽、连接超时、半连接队列，都跟这些概念有关。</p><p><strong>HTTP。</strong> HTTP/1.1、HTTP/2、HTTP/3的区别？Cookie、Session、Token的区别？HTTPS的握手过程？GET和POST的本质区别不是&quot;一个传参一个传body&quot;。</p><p><strong>判断你是否筑基成功的标准：</strong></p><p>问：浏览器输入URL到页面显示出来，中间发生了什么？</p><ul><li>炼气期回答：发请求，服务器返回HTML，浏览器渲染。</li><li>筑基期回答：DNS解析→TCP三次握手→TLS握手（HTTPS）→发HTTP请求→服务器处理→返回响应→浏览器解析HTML→构建DOM树和CSSOM→布局→绘制→合成。每一步如果展开，都能讲出细节。</li></ul><p>如果你能把这个链路讲清楚，知道每一步可能的性能瓶颈在哪，网络地基筑成了。</p><p><strong>筑基丹：</strong></p><ul><li>《计算机网络：自顶向下方法》——从应用层往下讲，最易懂</li><li>《图解HTTP》——入门级，适合快速过一遍</li></ul><hr><h2 id="修仙术语对照表" tabindex="-1">修仙术语对照表 <a class="header-anchor" href="#修仙术语对照表" aria-label="Permalink to &quot;修仙术语对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修仙概念</th><th>技术现实</th><th>一句话解释</th></tr></thead><tbody><tr><td>法器</td><td>数据结构</td><td>程序操作数据的工具（数组、链表、树、图、哈希）</td></tr><tr><td>功法</td><td>算法</td><td>计算进行的内在逻辑（排序、查找、DP、贪心）</td></tr><tr><td>天道规则</td><td>操作系统</td><td>所有程序运行的基本法则（进程、内存、IO）</td></tr><tr><td>传送阵</td><td>网络</td><td>连接不同系统的通道（TCP/IP、HTTP）</td></tr><tr><td>灵根</td><td>编程天赋</td><td>逻辑思维、数学基础、抽象能力</td></tr><tr><td>筑基丹</td><td>学习资源</td><td>帮助突破境界的经典教材和课程</td></tr></tbody></table><hr><h2 id="突破条件" tabindex="-1">突破条件 <a class="header-anchor" href="#突破条件" aria-label="Permalink to &quot;突破条件&quot;">​</a></h2><p>四座地基都筑成了，就算筑基成功。但筑基不是终点，是起点。</p><p>筑基之后，你要能回答一个核心问题：<strong>你写的代码，从源码到运行，中间发生了什么？</strong></p><p>这个问题展开就是一篇完整文章——编译、链接、加载、执行。这是从筑基期突破到金丹期的关键：从&quot;懂各部分原理&quot;到&quot;理解各部分怎么串起来&quot;。</p><p>下一篇讲这个链路：<strong>你的代码在CPU里到底跑了一圈——从源码到执行的完整链路</strong>。</p><hr><h2 id="下期预告-互动" tabindex="-1">下期预告 + 互动 <a class="header-anchor" href="#下期预告-互动" aria-label="Permalink to &quot;下期预告 + 互动&quot;">​</a></h2><blockquote><p><strong>下一篇：【筑基·05】你的代码在CPU里到底跑了一圈——从源码到执行的完整链路</strong></p></blockquote><p>现在问你：<strong>你现在处于哪个境界？</strong> 是还在炼气期写业务代码，还是已经筑基懂原理了？还是卡在某个地基上？评论区聊聊。</p><blockquote><p>我是玄芯散人，带你从炼气修到大乘。</p></blockquote><hr><p><em>本文是「码农修仙传」系列第4篇。系列导航见 <a href="https://xren.ren" target="_blank" rel="noreferrer">xren.ren</a></em></p>`,83)])])}const c=a(n,[["render",p]]);export{g as __pageData,c as default};
